package com.pockethub.launcher

import android.content.Context

/**
 * Launcher translations. The same 8 languages as PocketHub. English is the default.
 * The order of values in each row matches the order of LANGS.
 */
object I18n {
    val LANGS = listOf(
        "en" to "English",
        "ru" to "Русский",
        "de" to "Deutsch",
        "es" to "Español",
        "fr" to "Français",
        "it" to "Italiano",
        "nl" to "Nederlands",
        "zh" to "中文",
    )

    private const val PREFS = "settings"
    private const val KEY_LANG = "lang"

    var lang = "en"
        private set

    /** Increases on every language change. */
    var version = 0
        private set

    private var loaded = false
    private val listeners = mutableListOf<() -> Unit>()

    fun init(ctx: Context) {
        if (loaded) return
        loaded = true
        val saved = ctx.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getString(KEY_LANG, "en") ?: "en"
        lang = if (LANGS.any { it.first == saved }) saved else "en"
    }

    fun setLang(ctx: Context, code: String) {
        if (code == lang || LANGS.none { it.first == code }) return
        lang = code
        version++
        ctx.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().putString(KEY_LANG, code).apply()
        ArrayList(listeners).forEach { it() }
    }

    fun addListener(l: () -> Unit) { listeners += l }
    fun removeListener(l: () -> Unit) { listeners -= l }

    private fun index() = LANGS.indexOfFirst { it.first == lang }.coerceAtLeast(0)

    fun t(key: String): String {
        val row = S[key] ?: return key
        return row.getOrNull(index()) ?: row[0]
    }

    fun t(key: String, vararg args: Any): String = String.format(t(key), *args)

